&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience with late phase to commercial programs (cell therapy, gene&amp;nbsp;therapy&amp;nbsp;or biologics).&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:279}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
