&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;The&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;hiring&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;range for this role is&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;$&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;68,000&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;&amp;nbsp;- $&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;85,000&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;annually, in alignment to JF&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;F’s&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;Manager’s&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;s&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;alary band and our compensation philosophy. Starting salaries for new hires will be&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;determine&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;d&lt;/span&gt;&lt;span data-ccp-charstyle=&quot;normaltextrun&quot;&gt;&amp;nbsp;based on a combination of the new hire’s relevant experience and market demands.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:288}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;To&amp;nbsp;Apply&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt; &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;As part of your application, please include your resume and a thoughtful cover letter, addressed&amp;nbsp;to&lt;/span&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt; Lisa&amp;nbsp;Durkin,&lt;/span&gt;&lt;/em&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;outlining how your skills and experience meet the qualifications of the position.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are accepting applications through&lt;/span&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/em&gt;&lt;strong&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;June 23, 2026.&lt;/span&gt;&lt;/em&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Applications&amp;nbsp;submitted&amp;nbsp;by that date will be&amp;nbsp;reviewed,&amp;nbsp;and candidates will receive updates on their candidacy by the&amp;nbsp;first week&amp;nbsp;of&amp;nbsp;July.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;At JFF,&amp;nbsp;we’re&amp;nbsp;also committed to accessibility and want to ensure that everyone, including people with disabilities, can fully access and engage with our application and hiring process.&amp;nbsp;If you are unable to complete this application due to a disability&amp;nbsp;and/or have specific&amp;nbsp;access/accommodation needs&amp;nbsp;in order to&amp;nbsp;fully&amp;nbsp;participate&amp;nbsp;in our hiring process, please contact us&amp;nbsp;at&amp;nbsp;&lt;/span&gt;&lt;a href=&quot;mailto:hiringaccommodations@jff.org&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;hiringaccommodations@jff.org&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;none&quot;&gt;.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;Positions at JFF are not eligible for employer-visa sponsorship or open to F-1 student visa holders.&amp;nbsp;&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:2,&amp;quot;335551620&amp;quot;:2,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

leadershipforeducationalequity-zeta-char.descriptionHtml:
&lt;h4&gt;&lt;strong&gt;Follow your passion&amp;nbsp;&lt;/strong&gt;&lt;/h4&gt;
&lt;p&gt;Are you looking to make a BIG impact? At Zeta, we pursue an unprecedented combination of high academic achievement and social-emotional development for our students. We insist that every student receives a world-class education while fostering a love for learning. We are passionate about changing the landscape of public education in New York City and beyond, and we are uncompromising in our mission.&lt;/p&gt;
&lt;p&gt;Currently, we operate multiple elementary and middle schools in the &lt;strong&gt;Bronx and Upper Manhattan, and Queens.&lt;/strong&gt;&amp;nbsp;We plan to grow and open 1-2 schools each year because children in &lt;em&gt;every&lt;/em&gt; community deserve excellent, equitable education. Join our growing team today, and be a change agent for children.&lt;/p&gt;
&lt;p&gt;Our Network office is located at 401 W. 218th St., New York, NY 10034. Our Network team follows a hybrid work schedule: in-person work is required Tuesdays and Thursdays. School-facing roles such as this one may also require physical presence on other days, as required. &lt;strong&gt;It is projected for this role that on a regular basis, 3 to 4 in-person days per week will be required on average. In the first 2-3 months, more in person days may be required for you to get up to speed.&lt;/strong&gt;&lt;/p&gt;
&lt;h4&gt;&lt;strong&gt;Deliver powerful results&lt;/strong&gt;&lt;/h4&gt;
&lt;p&gt;To achieve our vision, we are searching for a stellar Managing Director of Operations Transformation with a Bachelor&#39;s Degree and 10+ years of experience and a proven record of building, optimizing, and scaling operational systems. The position title will be commensurate with candidate experience.&amp;nbsp;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Responsibilities:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;In this role, you will focus on building and implementing the highest-priority, scalable operational systems across Zeta schools. Reporting to the Chief Operating Officer, Schools, and with input from the CEO, this role is pivotal in removing barriers to achieving consistent world-class operations as Zeta scales schools across New York City. Several critical areas of operational and facilities excellence require deep analysis and redesign to build for scale.&lt;/p&gt;
&lt;p&gt;Below are illustrative projects that this leader will drive, though this is not an exhaustive list:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Build and operate a network-wide operating system for scale, creating a machine-like framework that maps and tracks operational priorities across schools and aligns stakeholders&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Evaluate existing operational practices, processes, systems, and roles across schools; identify inefficiencies, analyze root causes, and implement scalable solutions following an identification → root cause → solutions approach&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Unlock the full potential of safety systems by leveraging the full power of our advanced technologies (e.g., smart cameras, AI-powered monitoring) and strengthening accountability structures for both safety leaders and all Zeta staff&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Explore the highest value use cases for AI in operations (both at the Central Office and Schools), and pilot AI these applications (e.g. AI-powered family communications and an AI-enabled search of codified procedures and documents)&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Redesign professional development pathways for school-based operations staff, building codified training, role expectations, enhanced performance management processes, and career growth opportunities&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li&gt;Wearing multiple hats as a part of a lean scale-up team, supporting the work of others on the team and taking on new projects and tasks as needed&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;&lt;strong&gt;Join our purpose-driven community&lt;/strong&gt;&lt;/h4&gt;
&lt;p&gt;Zeta teammates are lifelong learners who live with child-like joy and a deep sense of purpose. We disrupt the status quo and tackle problems together. Our team stands united by our commitment to a limitless future for every child. Our Zeta team is comprised of top talent with incredible schooling and private sector experience. At Zeta:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;We are passionate about our mission of providing world-class education to all students&lt;/li&gt;
&lt;li&gt;We bring a mindset of growth, flexibility, and openness to feedback&lt;/li&gt;
&lt;li&gt;We are hungry and determined to not only meet our goals, but surpass them&lt;/li&gt;
&lt;li&gt;We are humble, willing to put the team’s needs ahead of our own, and committed to contributing to a collaborative work environment&lt;/li&gt;
&lt;li&gt;We have a high bar for excellence and sweat over the details&lt;/li&gt;
&lt;li&gt;We are caring and put team over individual at all times&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;We are accepting applications on a rolling basis&lt;/strong&gt;&lt;strong&gt;.&lt;/strong&gt; The salary range for this position is between $125,000 and $175,000. New hires can expect to be brought into the organization at a salary at or near the start of the range, depending on relevant experience and internal equity. Compensation is based on our salary scale . This position is eligible to receive an annual discretionary, merit-based performance bonus.&lt;/p&gt;
&lt;h4&gt;&lt;strong&gt;How does Zeta invest in you?&amp;nbsp;&lt;/strong&gt;&lt;/h4&gt;
&lt;p&gt;&lt;strong&gt;We offer great benefits:&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Comprehensive and affordable medical, dental, and vision plans&lt;/li&gt;
&lt;li&gt;Flexible spending accounts for eligible medical purchases and commuter expenses&lt;/li&gt;
&lt;li&gt;403(b) retirement plan; Zeta offers matching contributions toward your savings&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Competitive compensation&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;We provide awesome perks:&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Monthly stipend for wellness and lifestyle expenses (Gym memberships, salon appointments, concerts – it’s up to you!)&lt;/li&gt;
&lt;li&gt;4 live therapy sessions per month through Talkspace, and a free Headspace subscription&lt;/li&gt;
&lt;li&gt;MacBook Air, and specified monthly reimbursement for use of mobile phone&lt;/li&gt;
&lt;li&gt;Fully stocked teacher workrooms with favorite snacks and Nespresso machine&lt;/li&gt;
&lt;li&gt;Zeta swag, team outings, and NYC’s finest sweet treats&lt;/li&gt;
&lt;li&gt;Books for professional development&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;We care deeply about your personal and professional growth:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Clear pathway to professional growth&lt;/li&gt;
&lt;li&gt;Consistent feedback and support from managers and teammates&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Community Circle practice to build and strengthen our sense of team&lt;/li&gt;
&lt;li&gt;Interactive Mindfulness and DEIJ programming&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;Apply Now!&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;Equity is at the heart of our mission. We have a deep commitment to pursuing diversity and striving for equity. Zeta is an equal opportunity employer. Candidates of all backgrounds are encouraged to apply. Work authorization is required (candidate must have permanent authorization to work in the U.S.).&lt;/p&gt;

lsvp-grafana-labs:greenhouse:5971212004.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Grafana Labs, the company behind the open observability cloud, is founded on the principles of open source, open standards, open ecosystems, and open culture. Grafana Cloud, our fully managed observability platform, is flexible and built for scale. With Grafana Cloud&#39;s actually useful AI, organizations can see, understand, and act on all their disparate data to move at the speed of their ambitions. Today, more than 35 million users and 7,000+ customers – including Anthropic, Bloomberg, NVIDIA, Microsoft, and Salesforce – trust Grafana Labs to ensure reliability of their applications and systems, resolve incidents quickly, and optimize their telemetry to reduce noise and cost. We are a 100% remote company with 1,600+ team members across 40+ countries, and we’re backed by leading investors including Lightspeed Venture Partners, Sequoia Capital, GIC, Coatue, J.P. Morgan, CapitalG, and Lead Edge Capital. Learn more at &lt;u&gt;&lt;span&gt;&lt;a href=&quot;http://grafana.com&quot; target=&quot;_blank&quot;&gt;grafana.com&lt;/a&gt;&lt;/span&gt;&lt;/u&gt; and follow us on &lt;u&gt;&lt;span&gt;&lt;a href=&quot;https://www.linkedin.com/company/grafana-labs/&quot; target=&quot;_blank&quot;&gt;LinkedIn&lt;/a&gt;&lt;/span&gt;&lt;/u&gt; and &lt;u&gt;&lt;span&gt;&lt;a href=&quot;https://twitter.com/grafana&quot; target=&quot;_blank&quot;&gt;X&lt;/a&gt;&lt;/span&gt;&lt;/u&gt;.&lt;/p&gt;
&lt;p&gt;We’re scaling fast and staying true to what makes us different: an open-source legacy, a global collaborative culture, and a passion for meaningful work. Our team thrives in an innovation-driven environment where transparency, autonomy, and trust fuel everything we do.&lt;/p&gt;
&lt;p&gt;You may not meet every requirement, and that’s okay. If this role excites you, we’d love you to raise your hand for what could be a truly career-defining opportunity.&lt;/p&gt;&lt;/div&gt;&lt;p data-start=&quot;226&quot; data-end=&quot;603&quot;&gt;&lt;strong&gt;The Opportunity:&lt;/strong&gt;&lt;/p&gt;
&lt;p data-start=&quot;226&quot; data-end=&quot;603&quot;&gt;At Grafana Labs, we’re redefining what post-sales technical partnership looks like—and it starts with the&amp;nbsp;&lt;strong data-start=&quot;332&quot; data-end=&quot;359&quot;&gt;Observability Architect&lt;/strong&gt;. This is a role for deeply technical experts who are ready to step into strategic leadership with our most important customers. If you thrive at the intersection of systems thinking, architecture design, and customer impact—this is your stage.&lt;/p&gt;
&lt;p data-start=&quot;605&quot; data-end=&quot;1035&quot;&gt;As an Observability Architect, you will be the technical owner of long-term customer success. You’ll architect and guide the implementation of complex observability solutions across a wide range of modern infrastructure and application environments. You’ll build strategic relationships with engineers, SREs, and architects—ensuring Grafana’s technology is not just deployed, but &lt;strong data-start=&quot;985&quot; data-end=&quot;1004&quot;&gt;deeply embedded&lt;/strong&gt; into mission-critical systems.&lt;/p&gt;
&lt;p data-start=&quot;1037&quot; data-end=&quot;1339&quot;&gt;Working hand-in-hand with our Engagement Managers, you’ll lead technical discovery, design, onboarding, and enablement—all with a focus on delivering tangible outcomes. You’ll spot patterns, solve hard problems, and guide customers through their observability maturity curve with authority and clarity.&lt;/p&gt;
&lt;p data-start=&quot;1341&quot; data-end=&quot;1518&quot;&gt;You’ll also represent the technical voice of our customers internally—shaping product feedback and roadmap priorities by working closely with Engineering and Product Management.&lt;/p&gt;
&lt;p data-start=&quot;1520&quot; data-end=&quot;1735&quot;&gt;This is a hands-on, high-impact role for those who want to go deep, stay technical, and directly influence customer success at scale. Join us and become part of the most respected observability team in the industry.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What You&#39;ll Be Doing:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Serve as the primary technical point of contact for a portfolio of Grafana customers.&lt;/li&gt;
&lt;li&gt;Design the observability maturity journey of customers and assist them on that path.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Provide expert-level troubleshooting and guidance to drive adoption.&lt;/li&gt;
&lt;li&gt;Conduct regular technical reviews and health checks to ensure client success. Assist in RCA to understand issues that affect customer satisfaction, retention, and overall product experience.&lt;/li&gt;
&lt;li&gt;Advise clients on best practices and strategies for leveraging our technology to achieve their business goals&lt;/li&gt;
&lt;li&gt;Collaborate with clients to develop and execute technical roadmaps.&lt;/li&gt;
&lt;li&gt;Identify opportunities for clients to optimize their cost, expand their use of our solutions and drive adoption of new products and features.&lt;/li&gt;
&lt;li&gt;Develop and maintain strong, long-term relationships with key stakeholders.&lt;/li&gt;
&lt;li&gt;With the support of our Engagement Managers and Onboarding Solutions Architects, own customer lifecycle.&lt;/li&gt;
&lt;li&gt;Drive the adoption and effective use of our product suite within your customer portfolio to maximize their value from our platform and ensure a strong return on investment.&lt;/li&gt;
&lt;li&gt;Act as the voice of the customer within the company, advocating for their needs, priorities and feature requests.&lt;/li&gt;
&lt;li&gt;Conduct training sessions and workshops to educate clients on our technology.&lt;/li&gt;
&lt;li&gt;Develop and deliver technical documentation, guides, and tutorials.&lt;/li&gt;
&lt;li&gt;Work alongside account teams to participate in and/or conduct regular reviews with customers to identify areas for improvement, calculate ROI, assess their satisfaction, and discuss upcoming needs and projects.&lt;/li&gt;
&lt;li&gt;Prepare and present reports on client metrics, achievements, and areas of focus.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What Makes You a Great Fit:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Located on the West Coast&lt;/li&gt;
&lt;li&gt;Bachelor’s degree in Computer Science, Information Technology, Math or a related field (or equivalent experience).&lt;/li&gt;
&lt;li&gt;Experience deploying and operating Kubernetes.&lt;/li&gt;
&lt;li&gt;5+ years of experience in a technical support, technical account management, consulting, SE or Professional Services role within the technology industry.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Strong understanding of observability solutions. Grafana, Prometheus, and Loki a plus.&lt;/li&gt;
&lt;li&gt;Proven ability to manage multiple clients and projects simultaneously.&lt;/li&gt;
&lt;li&gt;Excellent problem-solving and analytical skills.&lt;/li&gt;
&lt;li&gt;Outstanding communication and interpersonal skills.&lt;/li&gt;
&lt;li&gt;Experience with relevant tools and technologies, e.g., CRM software, ticketing systems, specific programming languages.&lt;/li&gt;
&lt;li&gt;Ability to travel as needed to meet with clients (up to 25%).&lt;/li&gt;
&lt;li&gt;Identify and provide timely workarounds and solutions to meet a customer’s business needs.&lt;/li&gt;
&lt;li&gt;You have some observability expertise, preferably architect level&lt;/li&gt;
&lt;li&gt;First class written and oral communication skills to collaborate with our remote-first internal teams and with our worldwide customers.&amp;nbsp; Ability to articulate our value proposition and the technical advantages of our products&lt;/li&gt;
&lt;li&gt;You will love solving technical challenges and thrive on bringing creative solutions to our customers&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Bonus Points For:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;5+ years of technical sales, TAM or other post sales technical experience, ideally with open source technologies, or in the observability space.&lt;/li&gt;
&lt;li&gt;Great at connecting product usage to value (ROI).&lt;/li&gt;
&lt;li&gt;Great at managing customer lifecycle.&lt;/li&gt;
&lt;li&gt;You will be creative in solving customer adoption challenges.&lt;/li&gt;
&lt;li&gt;You can proactively assist customers with technical issues that may arise and assist in the troubleshooting and root cause analysis.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;You should have a technical mindset and a desire to grow technically. Great candidates may be a recent grad of a coding bootcamp or have previous post-sales or engineering experience–we are excited to see what unique experiences and skill sets you bring to the table!&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;In the US, the OTE compensation range for this role is $204,000 - $260,000. &amp;nbsp;Actual compensation may vary based on level, experience, and skillset as assessed throughout the interview process. All of our roles include Restricted Stock Units (RSUs), giving every team member ownership in Grafana Labs&#39; success. We believe in shared outcomes—RSUs help us stay aligned and invested as we scale globally.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div&gt;
&lt;p&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;*Compensation ranges are country specific. If you are applying for this role from a different location than listed above, your recruiter will discuss your specific market’s defined pay range &amp;amp; benefits at the beginning of the process.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Why You’ll Thrive at Grafana Labs:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;100% Remote, Global Culture -&amp;nbsp;&lt;/strong&gt;As a remote-only company, we bring together talent from around the world, united by a culture of collaboration and shared purpose.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Scaling Organization&lt;/strong&gt; – Tackle meaningful work in a high-growth, ever-evolving environment.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Transparent Communication&lt;/strong&gt; – Expect open decision-making and regular company-wide updates.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Innovation-Driven&lt;/strong&gt; – Autonomy and support to ship great work and try new things.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Open Source Roots&lt;/strong&gt; – Built on community-driven values that shape how we work.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Empowered Teams&lt;/strong&gt; – High trust, low ego culture that values outcomes over optics.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Career Growth Pathways&lt;/strong&gt; – Defined opportunities to grow and develop your career.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Approachable Leadership&lt;/strong&gt; – Transparent execs who are involved, visible, and human.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Passionate People&lt;/strong&gt; – Join a team of smart, supportive folks who care deeply about what they do.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;In-Person onboarding &lt;/strong&gt;- We want you to thrive from day 1 with your fellow new ‘Grafanistas’ to learn all about what we do and how we do it.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Balance is Key&lt;/strong&gt; - We operate a global annual leave policy of 30 days per annum. 3 days of your annual leave entitlement are reserved for Grafana Shutdown Days to allow the team to really disconnect. &lt;em&gt;*We will comply with local legislation where applicable.&lt;/em&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Equal Opportunity Employer:&lt;/strong&gt; &lt;em&gt;Grafana Labs is an equal opportunities employer. We welcome applications from everyone regardless of race, colour, nationality, origin, caste, sex, gender reassignment identity or expression, sexual orientation, age, religion or belief, disability, veteran status, genetic information, pregnancy, maternity, marital, family or carer status, or any other characteristic which is protected by local law. We believe that equality and diversity build a strong organisation, and we work hard to ensure that is the foundation of our organisation as we grow.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;Grafana Labs may utilize AI tools in its recruitment process to assist in matching information provided in CVs to job postings. The recruitment team will continue to review inbound CVs manually to identify alignment with current openings.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;#LI-Remote&lt;/p&gt;
&lt;/div&gt;
&lt;div&gt;&lt;em&gt;For information about how your personal data is used once you’ve applied to a job, check out our &lt;a href=&quot;https://grafana.com/legal/applicant-and-candidate-privacy-policy/&quot; target=&quot;_blank&quot;&gt;privacy policy&lt;/a&gt;.&amp;nbsp;&lt;/em&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;&lt;/div&gt;

lsvp-grafana-labs:greenhouse:6011362004.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Grafana Labs, the company behind the open observability cloud, is founded on the principles of open source, open standards, open ecosystems, and open culture. Grafana Cloud, our fully managed observability platform, is flexible and built for scale. With Grafana Cloud&#39;s actually useful AI, organizations can see, understand, and act on all their disparate data to move at the speed of their ambitions. Today, more than 35 million users and 7,000+ customers – including Anthropic, Bloomberg, NVIDIA, Microsoft, and Salesforce – trust Grafana Labs to ensure reliability of their applications and systems, resolve incidents quickly, and optimize their telemetry to reduce noise and cost. We are a 100% remote company with 1,600+ team members across 40+ countries, and we’re backed by leading investors including Lightspeed Venture Partners, Sequoia Capital, GIC, Coatue, J.P. Morgan, CapitalG, and Lead Edge Capital. Learn more at &lt;u&gt;&lt;span&gt;&lt;a href=&quot;http://grafana.com&quot; target=&quot;_blank&quot;&gt;grafana.com&lt;/a&gt;&lt;/span&gt;&lt;/u&gt; and follow us on &lt;u&gt;&lt;span&gt;&lt;a href=&quot;https://www.linkedin.com/company/grafana-labs/&quot; target=&quot;_blank&quot;&gt;LinkedIn&lt;/a&gt;&lt;/span&gt;&lt;/u&gt; and &lt;u&gt;&lt;span&gt;&lt;a href=&quot;https://twitter.com/grafana&quot; target=&quot;_blank&quot;&gt;X&lt;/a&gt;&lt;/span&gt;&lt;/u&gt;.&lt;/p&gt;
&lt;p&gt;We’re scaling fast and staying true to what makes us different: an open-source legacy, a global collaborative culture, and a passion for meaningful work. Our team thrives in an innovation-driven environment where transparency, autonomy, and trust fuel everything we do.&lt;/p&gt;
&lt;p&gt;You may not meet every requirement, and that’s okay. If this role excites you, we’d love you to raise your hand for what could be a truly career-defining opportunity.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;The Opportunity:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;This is a full time remote role for applicants in the United Kingdom or Ireland only. We are looking for candidates who have experience supporting Sales or customer facing orgs as a business partner, but whose true passion, experience and interest is enabling those teams and leaders on a daily basis.&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p data-start=&quot;324&quot; data-end=&quot;655&quot;&gt;This is an exciting opportunity to join our already strong People Business Partnering function at Grafana Labs. You will report to our Sr. Manager, People Business Partnering and form a critical part of our GTM Business Partnering team, supporting the global design, implementation and delivery of our People enablement strategy.&lt;/p&gt;
&lt;p data-start=&quot;997&quot; data-end=&quot;1534&quot;&gt;Our ideal candidate will comfortably drive the strategic enablement planning process for the GTM organisation and cross-functionally partner on their learning and performance priorities, needs, and enablement goals. You will understand the interplay between retention, people management, and leadership enablement and have the experience to make a meaningful impact on those objectives. If you enjoy variety, a broad scope, and partnering with leadership to drive real change and development within their teams, this role may be for you.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What You’ll Be Doing:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;You will partner directly with our GTM management and leadership teams building trusted advisor status with key stakeholders&lt;/li&gt;
&lt;li&gt;You will help design and lead the annual delivery of the org’s People Plan agenda as it relates to any learning, performance or development topics&lt;/li&gt;
&lt;li&gt;This will include the facilitation and presentation of enablement based topics both ad-hoc / remotely and at global as well as regional departmental in-person offsites&amp;nbsp;&lt;/li&gt;
&lt;li&gt;You will identify needs, gaps &amp;amp; opportunities within the team’s current people management structure in an effort to improve their overall organisational health metrics&amp;nbsp;&lt;/li&gt;
&lt;li&gt;You will support new and experienced people managers across the GTM function to ensure we build a strong and consistent approach to people management&amp;nbsp;&lt;/li&gt;
&lt;li&gt;You will partner with our People team to deliver our annual People processes surrounding talent &amp;amp; performance, attrition &amp;amp; retention and learning initiatives&amp;nbsp;&lt;/li&gt;
&lt;li&gt;You will have the professional knowledge to actively contribute to the enhancement and delivery of these enablement processes, as well as provide your experienced perspective on how to improve these initiatives on an ongoing basis&lt;/li&gt;
&lt;li&gt;You will use AI tools and LLMs of your choosing to build lightweight, prompt-driven enablement workflows—such as generating personalised manager coaching briefs from 360 feedback and engagement data, creating AI-assisted “manager readiness” diagnostics that produce tailored development plans, and using sentiment analysis to measure enablement impact&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What Makes You a Great Fit:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Ideally you’ll have done this before—you have experience in a high-growth environment; you will also have experience partnering with GTM management teams at a strategic level&lt;/li&gt;
&lt;li&gt;Ideally you have experience of working remotely and internationally coordinating with team members globally and understand the challenges and opportunities of remote work and communication&lt;/li&gt;
&lt;li&gt;You are process oriented and enjoy creating structure where there may be ambiguity and are skilled at finding creative solutions to non-obvious problems&lt;/li&gt;
&lt;li&gt;You are an excellent communicator in all channels (in-person, over Zoom, in Slack) and you’re able to garner strong working relationships as a result&amp;nbsp;&lt;/li&gt;
&lt;li&gt;You are a people-person and problem solver at heart - you are able to take your passion for helping others and identifying problems to ultimately define solutions and drive impact&lt;/li&gt;
&lt;li&gt;You appreciate working in a team through competing priorities and are able to use your initiative and creative problem solving to confidently manage decision-making&amp;nbsp;&amp;nbsp;&lt;/li&gt;
&lt;li&gt;You will be highly approachable while successfully being able to provide a customer service approach to your role ensuring that everyone, locally and internationally, views you as a “go to” person for enablement and development&lt;/li&gt;
&lt;li&gt;You are AI-fluent, tool-agnostic, and instinctively reach for LLMs to accelerate your work—whether that’s synthesising survey and attrition data to surface people-management patterns, prototyping workshop content and roleplay scenarios in hours instead of weeks, or building prompt-driven workflows that personalise enablement at scale.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Bonus Points For:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Experience working in startup or high-growth technology environments, particularly within SaaS companies, is strongly preferred.&lt;/li&gt;
&lt;li&gt;You have strong experience facilitating and presenting on a wide array of topics including enablement led discussion. Obtaining a coaching certification is a plus.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Compensation &amp;amp; Rewards:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;In the Republic of Ireland, the OTE (On-Target Earnings) compensation range for this role is EUR 81,000 - GBP 98,000. Actual compensation may vary based on level, experience, and skillset as assessed throughout the interview process. All of our roles include Restricted Stock Units (RSUs), giving every team member ownership in Grafana Labs&#39; success. We believe in shared outcomes—RSUs help us stay aligned and invested as we scale globally.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div&gt;
&lt;p&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;*Compensation ranges are country specific. If you are applying for this role from a different location than listed above, your recruiter will discuss your specific market’s defined pay range &amp;amp; benefits at the beginning of the process.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Why You’ll Thrive at Grafana Labs:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;100% Remote, Global Culture -&amp;nbsp;&lt;/strong&gt;As a remote-only company, we bring together talent from around the world, united by a culture of collaboration and shared purpose.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Scaling Organization&lt;/strong&gt; – Tackle meaningful work in a high-growth, ever-evolving environment.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Transparent Communication&lt;/strong&gt; – Expect open decision-making and regular company-wide updates.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Innovation-Driven&lt;/strong&gt; – Autonomy and support to ship great work and try new things.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Open Source Roots&lt;/strong&gt; – Built on community-driven values that shape how we work.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Empowered Teams&lt;/strong&gt; – High trust, low ego culture that values outcomes over optics.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Career Growth Pathways&lt;/strong&gt; – Defined opportunities to grow and develop your career.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Approachable Leadership&lt;/strong&gt; – Transparent execs who are involved, visible, and human.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Passionate People&lt;/strong&gt; – Join a team of smart, supportive folks who care deeply about what they do.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;In-Person onboarding &lt;/strong&gt;- We want you to thrive from day 1 with your fellow new ‘Grafanistas’ to learn all about what we do and how we do it.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Balance is Key&lt;/strong&gt; - We operate a global annual leave policy of 30 days per annum. 3 days of your annual leave entitlement are reserved for Grafana Shutdown Days to allow the team to really disconnect. &lt;em&gt;*We will comply with local legislation where applicable.&lt;/em&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Equal Opportunity Employer:&lt;/strong&gt; &lt;em&gt;Grafana Labs is an equal opportunities employer. We welcome applications from everyone regardless of race, colour, nationality, origin, caste, sex, gender reassignment identity or expression, sexual orientation, age, religion or belief, disability, veteran status, genetic information, pregnancy, maternity, marital, family or carer status, or any other characteristic which is protected by local law. We believe that equality and diversity build a strong organisation, and we work hard to ensure that is the foundation of our organisation as we grow.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em data-stringify-type=&quot;italic&quot;&gt;Grafana Labs may utilize AI tools in its recruitment process to assist in matching information provided in CVs to job postings. The recruitment team will continue to review inbound CVs manually to identify alignment with current openings.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;#LI-Remote&lt;/p&gt;
&lt;/div&gt;
&lt;div&gt;&lt;em&gt;For information about how your personal data is used once you’ve applied to a job, check out our &lt;a href=&quot;https://grafana.com/legal/applicant-and-candidate-privacy-policy/&quot; target=&quot;_blank&quot;&gt;privacy policy&lt;/a&gt;.&amp;nbsp;&lt;/em&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;&lt;/div&gt;

lsvp-nas-company:greenhouse:7701619003.descriptionHtml:
&lt;div data-page-id=&quot;NOjLd43QJo1DLYxADLxuPSfusrh&quot; data-lark-html-role=&quot;root&quot; data-docx-has-block-data=&quot;false&quot;&gt;&lt;strong&gt;Full-time, Hybrid&amp;nbsp;&lt;/strong&gt;&lt;br&gt;&lt;br&gt;
&lt;div data-lark-html-role=&quot;root&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;3&quot;&gt;At &lt;strong&gt;&lt;a href=&quot;https://nas.com/&quot;&gt;Nas.com&lt;/a&gt;&lt;/strong&gt;&lt;/span&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;5-0&quot;&gt;, we’re building the future of online business. Our AI-powered platform helps solopreneurs and professionals transform ideas into thriving digital products—fast, simple, and low-cost. With &lt;span class=&quot;text-only&quot; data-eleid=&quot;3&quot;&gt;&lt;strong&gt;&lt;a href=&quot;https://nas.com/&quot;&gt;Nas.com&lt;/a&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;5-2&quot;&gt;, anyone can go from concept to creation: launch a product, find their first customers, and generate their first revenue online in minutes.&amp;nbsp;&lt;/span&gt;&lt;/div&gt;
&lt;div data-lark-html-role=&quot;root&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;8&quot;&gt;Founded by the team behind Nas Daily, whose content reaches over 500 million people every month, we are a global team of 100 people serving users around the world, united by one mission: to make starting and scaling an online business easier than ever before.&lt;/span&gt;&lt;/div&gt;
&lt;br&gt;
&lt;h3 class=&quot;heading-3 ace-line old-record-id-NB8VdawF5oHGsfxGWEYuY7MfsLb&quot;&gt;&lt;strong&gt;Position Overview&lt;/strong&gt;&lt;/h3&gt;
&lt;div class=&quot;ace-line ace-line old-record-id-Zuscdct6UoJKVoxoK0Gu2sOysQd&quot;&gt;Nas.com is seeking a &lt;strong&gt;Senior Backend Engineer&lt;/strong&gt; to support and scale our backend systems for a fast-growing creator platform. This is a full-time&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;role open to candidates in China. The ideal candidate thrives in an&amp;nbsp;&lt;strong&gt;asynchronous work environment&lt;/strong&gt;, can work independently, and is passionate about improving product reliability, system architecture, and performance. You will play a key role in ensuring our platform remains robust and responsive around the clock.&lt;/div&gt;
&lt;div class=&quot;ace-line ace-line old-record-id-GWcodtKi7oM1IWxGutuulApZsAb&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;div class=&quot;ace-line ace-line old-record-id-GWcodtKi7oM1IWxGutuulApZsAb&quot;&gt;&lt;strong&gt;Key Responsibilities&lt;/strong&gt;&lt;/div&gt;
&lt;ul class=&quot;list-bullet1&quot;&gt;
&lt;li class=&quot;ace-line ace-line old-record-id-QHz7du2fPo8yz4xFSRhuAPLZsRd&quot; data-list=&quot;bullet&quot;&gt;
&lt;div&gt;&lt;strong&gt;Backend Feature Development:&lt;/strong&gt; Collaborate with product managers to design and implement new backend features that align with business goals and user needs. Ensure features are delivered from concept to deployment with high quality.&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;ace-line ace-line old-record-id-EszadLXjRonFRvx3iP7u6t2QsAd&quot; data-list=&quot;bullet&quot;&gt;
&lt;div&gt;&lt;strong&gt;System Architecture &amp;amp; Performance:&lt;/strong&gt; Continuously improve the architecture of our core systems for better performance, scalability, and maintainability. Participate in technical design discussions and make decisions to enhance system reliability.&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;ace-line ace-line old-record-id-MFQvduLLBo6W2ixHAy7uc5OOs4f&quot; data-list=&quot;bullet&quot;&gt;
&lt;div&gt;&lt;strong&gt;Infrastructure &amp;amp; DevOps:&lt;/strong&gt; Enhance and maintain our infrastructure (AWS cloud services and related tooling). Set up and refine CI/CD pipelines as needed to streamline deployments.&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;ace-line ace-line old-record-id-U4BVd0AC4opY2lx7TizudTlLsBd&quot; data-list=&quot;bullet&quot;&gt;
&lt;div&gt;&lt;strong&gt;Monitoring &amp;amp; Alerts:&lt;/strong&gt; Establish and fine-tune comprehensive monitoring, logging, and alerting across all platforms. Maintain observability tools to ensure any issues are detected early and accurately, enabling rapid response.&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;ace-line ace-line old-record-id-Up5mdbcSkoKTKex663wuTAcxs1f&quot; data-list=&quot;bullet&quot;&gt;
&lt;div&gt;&lt;strong&gt;Off-Hours Support:&lt;/strong&gt; Serve as the point person for troubleshooting and responding to backend system issues during off-peak hours (EU daytime / APAC night). Promptly address incidents, mitigate impact, and escalate to the broader engineering team if critical issues arise outside your expertise.&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;ace-line ace-line old-record-id-TDpsdd5eio0IBNxT7xFuldLJske&quot; data-list=&quot;bullet&quot;&gt;
&lt;div&gt;&lt;strong&gt;Quality &amp;amp; Best Practices:&lt;/strong&gt; Uphold high code quality standards through code reviews, testing, and documentation. Introduce best practices for coding, error handling, and performance optimization across the backend team.&lt;/div&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 class=&quot;heading-3 ace-line old-record-id-Y7mCdtnfEoeQzHxxL9quwZwGsee&quot;&gt;&lt;strong&gt;Qualifications &amp;amp; Skills&lt;/strong&gt;&lt;/h3&gt;
&lt;ul class=&quot;list-bullet1&quot;&gt;
&lt;li class=&quot;ace-line ace-line old-record-id-FiyKdVpf8oHdPXxCwJfuuQC3sIh&quot; data-list=&quot;bullet&quot;&gt;
&lt;div&gt;&lt;strong&gt;Experience:&lt;/strong&gt; 4+ years in backend development or systems engineering roles, with a strong track record of building and maintaining scalable systems.&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;ace-line ace-line old-record-id-DoQXdOsvBoqEbyxjExnuQJ7esHg&quot; data-list=&quot;bullet&quot;&gt;
&lt;div&gt;&lt;strong&gt;Backend Proficiency:&lt;/strong&gt; Hands-on experience in one or more backend programming languages and frameworks (&lt;strong&gt;Node.js&lt;/strong&gt;, &lt;strong&gt;Python&lt;/strong&gt;) for building APIs and services.&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;ace-line ace-line old-record-id-N81QdiCoqoSQL3xgFlhuA73Xsyd&quot; data-list=&quot;bullet&quot;&gt;
&lt;div&gt;&lt;strong&gt;Databases &amp;amp; Caching:&lt;/strong&gt; Solid experience working with databases (especially &lt;strong&gt;MongoDB&lt;/strong&gt; or other NoSQL/SQL databases) and caching systems like &lt;strong&gt;Redis&lt;/strong&gt; to build efficient data-driven applications.&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;ace-line ace-line old-record-id-RikxdfHXSoMsLHxPkT5uN4fDsZc&quot; data-list=&quot;bullet&quot;&gt;
&lt;div&gt;&lt;strong&gt;Cloud Infrastructure:&lt;/strong&gt; Familiarity with cloud platforms, preferably &lt;strong&gt;AWS&lt;/strong&gt;, including services such as EC2, S3, Lambda, etc. Ability to manage and optimize cloud resources for cost and performance.&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;ace-line ace-line old-record-id-STZodUUaboLsKSxafNXuBewVslg&quot; data-list=&quot;bullet&quot;&gt;
&lt;div&gt;&lt;strong&gt;Observability:&lt;/strong&gt; Experience with observability and monitoring tools (for example, setting up dashboards, logs, and alerts using services like CloudWatch, Datadog, or Grafana/Prometheus) to ensure system health and performance.&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;ace-line ace-line old-record-id-TPzcdhCVHooB9UxPSNSuHQDAs8a&quot; data-list=&quot;bullet&quot;&gt;
&lt;div&gt;&lt;strong&gt;Autonomous Work:&lt;/strong&gt; Proven ability to work autonomously and take initiative in a &lt;strong&gt;remote, asynchronous environment&lt;/strong&gt;. You should be comfortable making progress with limited supervision and adept at communicating progress or issues in writing.&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;ace-line ace-line old-record-id-VLC1dUhlfokfnfx8SvmuZvpassh&quot; data-list=&quot;bullet&quot;&gt;
&lt;div&gt;&lt;strong&gt;Problem-Solving Skills:&lt;/strong&gt; Strong debugging and problem-solving abilities, especially under time pressure when responding to incidents. Capable of systematically diagnosing issues across a complex system (from application to database to infrastructure).&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;ace-line ace-line old-record-id-ZDZqdsISgobuFMxG8Q0uaLFOsih&quot; data-list=&quot;bullet&quot;&gt;
&lt;div&gt;&lt;strong&gt;Bonus Points:&lt;/strong&gt; Prior experience at a startup or in a fast-paced tech company. Such background demonstrates adaptability and the ability to handle broad responsibilities beyond a narrow role definition.&lt;/div&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;div class=&quot;rich-text-paragraph&quot; data-eleid=&quot;2&quot;&gt;&lt;strong&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;3&quot;&gt;Why work with us:&lt;/span&gt;&lt;/strong&gt;&lt;/div&gt;
&lt;div class=&quot;rich-text-paragraph&quot; data-eleid=&quot;2&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;div class=&quot;rich-text-paragraph&quot; data-eleid=&quot;4&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;5&quot;&gt;Here, you are not just an employee — you are treated as a true owner of the company. Our CEO shares clear updates on business strategy and operations every week, and your ideas are always welcome. You’ll have direct access to leadership, and strong support to turn great ideas into reality.&lt;/span&gt;&lt;/div&gt;
&lt;div class=&quot;rich-text-paragraph&quot; data-eleid=&quot;6&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;7&quot;&gt;You’ll work alongside a team of highly intelligent, passionate, and execution-driven engineers, using some of the most advanced AI technologies in the industry to solve real problems for users around the world.&lt;/span&gt;&lt;/div&gt;
&lt;div class=&quot;jobs-box--fadein jobs-box--full-width jobs-box--with-cta-large jobs-description



